def page(title,desc,body,path='/'):
  links=''.join(f'<a href="/{u}/">{n}</a>' for n,u in nav)
  return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta name="description" content="{escape(desc)}"><meta name="robots" content="noindex,nofollow,noarchive"><link rel="canonical" href="https://alankyeong.com{path}"><link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/assets.css?v=1.4"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:image" content="https://alankyeong.com/images/hero.jpg"><title>{escape(title)}</title></head><body><header class="site-header"><div class="wrap nav-wrap"><a class="brand" href="/">Alan Yeong<span>Asia insight &amp; strategy</span></a><button class="menu" aria-expanded="false">Menu</button><nav id="main-nav">{links}<a class="button small" href="/contact/">Discuss a project</a></nav></div></header><main>{body}</main><footer><div class="wrap footer-grid"><div><a class="brand light" href="/">Alan Yeong<span>Asia insight &amp; strategy</span></a><p>Asia-focused consumer intelligence and growth advisor.</p></div><div><h2>Explore</h2>{links}</div><div><h2>Elsewhere</h2><a href="https://ai.alankyeong.com/" target="_blank">Dedicated AI website ↗</a><a href="https://www.linkedin.com/in/alankyeong" target="_blank">LinkedIn ↗</a><a href="/privacy-policy/">Privacy policy</a></div></div><div class="wrap legal">© 2026 Alan Yeong.</div></footer><script>const b=document.querySelector('.menu'),n=document.querySelector('#main-nav');b.onclick=()=>{{let o=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',!o);n.classList.toggle('open',!o)}};document.querySelectorAll('[data-story]').forEach(t=>t.addEventListener('click',()=>{{document.querySelectorAll('.story-tab,.story-panel').forEach(x=>x.classList.remove('active'));t.classList.add('active');document.querySelector('#story-'+t.dataset.story)?.classList.add('active')}}));</script></body></html>'''
form='''<form class="contact-form" action="/api/contact.php" method="post"><input class="honeypot" name="website" tabindex="-1"><label>Name<input name="name" required></label><label>Work email<input type="email" name="email" required></label><label>Organisation<input name="organisation"></label><label>Area of interest<select name="interest" required><option value="">Select</option><option>Asia market entry</option><option>Consumer intelligence</option><option>Research advisory</option><option>AI Business Playbooks</option></select></label><label class="full">Market or region<input name="market"></label><label class="full">Message<textarea name="message" rows="6" required></textarea></label><label class="consent full"><input type="checkbox" name="consent" value="yes" required> I consent to Alan Yeong using this information to respond to my enquiry.</label><button class="button full">Send professional enquiry</button></form>'''
home='''<section class="hero"><div class="wrap hero-grid"><div><p class="eyebrow">Consumer Intelligence · Market Strategy · Practical AI</p><h1>Understand Asia. Make better decisions. Turn insight into action.</h1><p class="lead">I help business leaders navigate markets, consumers and commercial opportunities across Asia—connecting evidence, local context and commercial priorities.</p><div class="actions"><a class="button" href="#expertise">Explore my expertise</a><a class="button secondary" href="/contact/">Discuss an enquiry</a></div></div><img class="hero-photo" src="/images/hero.jpg" alt="Alan Yeong reviewing market evidence"></div></section><div class="proof"><div class="wrap proof-grid"><div class="proof-item"><strong>25 years</strong>Cross-functional experience</div><div class="proof-item"><strong>Across Asia</strong>Regional perspective</div><div class="proof-item"><strong>Research to leadership</strong>Multidisciplinary thinking</div><div class="proof-item"><strong>Human insight + AI</strong>Decision support</div></div></div><section id="expertise"><div class="wrap"><div class="section-head"><p class="eyebrow">Where I help</p><h2>From market understanding to confident action</h2><p>Good decisions require more than data. They require context, interpretation and an understanding of how markets and people actually behave.</p></div><div class="cards"><article class="card image-card"><img src="/images/market-entry.jpg" alt="Market evidence and decision pathways"><div class="card-copy"><h3>Asia market entry</h3><p>Examine opportunity, assumptions and local realities.</p></div></article><article class="card image-card"><img src="/images/consumer-intelligence.jpg" alt="Observation of consumer behaviour in an Asian market"><div class="card-copy"><h3>Consumer intelligence</h3><p>Turn fragmented evidence into a coherent strategic picture.</p></div></article><article class="card image-card"><img src="/images/research-interpretation.jpg" alt="Research evidence being organised for strategic interpretation"><div class="card-copy"><h3>Research interpretation</h3><p>Move from findings to direction and action.</p></div></article><article class="card image-card"><img src="/images/ai-playbook.jpg" alt="A practical AI-enabled workflow"><div class="card-copy"><h3>AI business playbooks</h3><p>Connect practical AI to responsible judgement.</p></div></article></div></div></section><section class="founder-section"><div class="wrap"><div class="section-head"><p class="eyebrow">Founder & Builder</p><h2>Ideas translated into ventures</h2><p>My work extends beyond advising organisations. I also build ventures that apply research, strategy, technology and consumer understanding in different ways.</p></div><div class="venture-grid"><details class="venture-card"><summary><span>BRG Consultancy</span><small>Founder · Consulting & Advisory</small></summary><p>A consulting platform connecting consumer intelligence, market understanding and strategic interpretation to real business decisions.</p></details><details class="venture-card"><summary><span>Illumera.ai</span><small>Founder · AI & Consumer Intelligence</small></summary><p>An AI venture exploring how evidence, signals and human judgement can support clearer consumer and market decisions.</p></details><details class="venture-card"><summary><span>Sakuragawa By Mihachinodo</span><small>Founder · Brand & Entrepreneurship</small></summary><p>A consumer-facing venture demonstrating the practical work of building a proposition, brand experience and business from the ground up.</p></details></div><a class="text-link" href="/about/#founder-story">Explore the founder story →</a></div></section><section class="alternate"><div class="wrap split"><div><p class="eyebrow">Asia expertise</p><h2>Asia is not one market</h2><p>Every market has its own cultural context, consumer behaviour and competitive structure.</p><a class="button" href="/asia-expertise/">Explore my Asia perspective</a></div><img class="section-photo" src="/images/asia-expertise.jpg" alt="Asian market evidence"></div></section><section><div class="wrap split"><div><p class="eyebrow">Career journey</p><h2>A perspective built across disciplines</h2><p>Market research taught me to investigate questions. Consumer intelligence taught me to look beneath reported behaviour. Banking, marketing and commercial leadership connected insight to operational realities. Consulting brought these perspectives together.</p><div class="journey"><span>Research</span><span>Consumer Intelligence</span><span>Banking</span><span>Marketing</span><span>Commercial Leadership</span><span>Consulting</span><span>AI-Enabled Advisory</span></div><a class="button secondary" href="/about/">Read my story</a></div><img class="section-photo" src="/images/career-journey.jpg" alt="A visual journey across Alan Yeong's multidisciplinary career"></div></section><section class="alternate"><div class="wrap split"><img class="section-photo" src="/images/thought-leadership.jpg" alt="Writing and reviewing ideas on markets, consumers and AI"><div><p class="eyebrow">Featured insights</p><h2>Ideas for leaders navigating Asia, consumers and AI</h2><p>I write about market realities, consumer behaviour, research practice, commercial judgement and the responsible use of AI.</p><a class="button" href="/insights/">View all insights</a></div></div></section><section><div class="wrap split"><div><p class="eyebrow">Advisory services</p><h2>Senior experience for consequential decisions</h2><p>Engagements can include executive advisory, market-entry assessment, consumer intelligence, research interpretation, strategic workshops, AI playbooks and leadership briefings. The work is shaped around the decision—not a predetermined package.</p><a class="button" href="/advisory/">Explore advisory services</a></div><img class="section-photo" src="/images/advisory-conversation.jpg" alt="A focused professional advisory conversation"></div></section><section class="alternate"><div class="wrap"><div class="section-head"><p class="eyebrow">Credibility</p><h2>Rigour, responsibility and local perspective</h2><p>The best measure of advisory work is whether it helps people understand a situation more clearly and make a better decision.</p></div><div class="evidence-strip"><div class="evidence-item"><strong>25 years</strong>Cross-functional professional experience</div><div class="evidence-item"><strong>Research to action</strong>Evidence interpreted for real decisions</div><div class="evidence-item"><strong>Founder perspective</strong>Advice informed by building ventures</div><div class="evidence-item"><strong>Human-led AI</strong>Technology with judgement and accountability</div></div></div></section><section><div class="wrap split"><div><p class="eyebrow">Practical AI</p><h2>Make AI useful for the work that matters</h2><p>AI becomes valuable when connected to evidence and responsible human judgement.</p><div class="actions"><a class="button" href="/ai-business-playbooks/">Explore AI Playbooks</a><a class="button secondary" href="https://ai.alankyeong.com/" target="_blank">Visit AI website ↗</a></div></div><img class="section-photo" src="/images/ai-playbook.jpg" alt="AI-enabled workflow"></div></section><section class="alternate"><div class="wrap narrow linkedin-panel"><p class="eyebrow">LinkedIn</p><h2>Continue the conversation</h2><p>I share shorter observations on Asian markets, consumer intelligence, business strategy, AI and the lessons that emerge from practical experience.</p><a class="button secondary" href="https://www.linkedin.com/in/alankyeong" target="_blank" rel="noopener">Follow Alan on LinkedIn ↗</a></div></section>'''
pages={'':('Alan Yeong | Asia Consumer Intelligence, Market Strategy & AI','Asia-focused consumer intelligence and market strategy.',home),'about':('About Alan Yeong | Asia Market Experience','A multidisciplinary perspective.','<header class="page-hero"><div class="wrap about-hero"><div><p class="eyebrow">About Alan</p><h1>From understanding consumers to building businesses</h1><p class="lead">My perspective has been shaped across research, banking, marketing, commercial leadership, consulting, entrepreneurship and practical AI.</p></div><img class="portrait-photo" src="/images/alan-portrait.png" alt="Portrait of Alan Yeong"></div></header><section class="story-section"><div class="wrap"><div class="section-head"><p class="eyebrow">Career journey</p><h2>A perspective built across disciplines</h2><p>Select a stage to explore how each part of my career contributes to the way I work today.</p></div><div class="story-tabs" role="tablist" aria-label="Career stages"><button class="story-tab active" data-story="research">Research</button><button class="story-tab" data-story="commercial">Commercial leadership</button><button class="story-tab" data-story="consulting">Consulting</button><button class="story-tab" data-story="founder">Founder</button><button class="story-tab" data-story="ai">Practical AI</button></div><div class="story-panels"><article class="story-panel active" id="story-research"><h3>Research and consumer intelligence</h3><p>Learning how to frame questions, examine evidence and understand the behaviour behind reported answers created the foundation of my work.</p></article><article class="story-panel" id="story-commercial"><h3>Banking, marketing and commercial leadership</h3><p>Working closer to operations and commercial realities taught me that insight matters only when it improves a choice, priority or action.</p></article><article class="story-panel" id="story-consulting"><h3>Consulting and strategic interpretation</h3><p>Consulting brought these disciplines together: evidence, local context, organisational constraints and the responsibility to provide direction when the answer is not obvious.</p></article><article class="story-panel" id="story-founder"><h3>Building ventures</h3><p>Founding businesses moved me from advising decisions to living with them—shaping propositions, brands, systems and customer experiences under real constraints.</p></article><article class="story-panel" id="story-ai"><h3>Human-led, AI-enabled work</h3><p>I now explore where AI can strengthen research, synthesis and knowledge work while keeping contextual judgement and accountability human.</p></article></div></div></section><section class="founder-section alternate" id="founder-story"><div class="wrap"><div class="section-head"><p class="eyebrow">Founder portfolio</p><h2>Three ventures, one connected philosophy</h2><p>Each venture applies a different part of my experience. Together, they show how consumer understanding can move from evidence to advice, technology and brand creation.</p></div><div class="venture-grid"><details class="venture-card" open><summary><span>BRG Consultancy</span><small>Founder · Consulting & Advisory</small></summary><p>BRG Consultancy represents my work in consumer intelligence, market strategy, research interpretation and senior advisory.</p><p><strong>What it demonstrates:</strong> translating evidence and local context into clearer commercial decisions.</p></details><details class="venture-card"><summary><span>Illumera.ai</span><small>Founder · AI & Consumer Intelligence</small></summary><p>Illumera.ai represents the technology and system-building dimension of my work in evidence-led consumer and market intelligence.</p><p><strong>What it demonstrates:</strong> building responsible AI around real decision needs rather than technology for its own sake.</p></details><details class="venture-card"><summary><span>Sakuragawa By Mihachinodo</span><small>Founder · Brand & Entrepreneurship</small></summary><p>Sakuragawa By Mihachinodo represents the experience of creating and shaping a consumer-facing proposition.</p><p><strong>What it demonstrates:</strong> applying consumer understanding through brand, product, experience and entrepreneurship.</p></details></div></div></section><section><div class="wrap split"><div><p class="eyebrow">Working philosophy</p><h2>Evidence first. Context always. Action with responsibility.</h2><p>I do not see research, commercial strategy, entrepreneurship and AI as separate worlds. They are different parts of the same journey from understanding a situation to making and executing a better decision.</p><a class="button" href="/contact/">Discuss a professional enquiry</a></div><img class="section-photo" src="/images/career-journey.jpg" alt="Editorial representation of a multidisciplinary career journey"></div></section>'),'advisory':('Asia Market, Consumer Intelligence & AI Advisory | Alan Yeong','Senior advisory for consequential decisions.','<header class="page-hero"><div class="wrap narrow"><p class="eyebrow">Advisory</p><h1>Senior experience for consequential decisions</h1></div></header><section><div class="wrap cards"><article class="card"><h2>Market entry</h2><p>Evaluate opportunities and assumptions.</p></article><article class="card"><h2>Consumer intelligence</h2><p>Connect behaviour to commercial choices.</p></article><article class="card"><h2>Research advisory</h2><p>Strengthen questions and interpretation.</p></article><article class="card"><h2>AI workflows</h2><p>Develop practical playbooks.</p></article></div></section>'),'asia-expertise':('Asia Market Entry and Regional Expertise | Alan Yeong','Country-level context for Asian market decisions.','<header class="page-hero"><div class="wrap narrow"><h1>Asia is not one market</h1></div></header><div class="page-body wrap narrow prose"><img src="/images/asia-expertise.jpg" alt="Asian market evidence"><h2>What travels—and what does not</h2><p>Capabilities may travel. Consumer meaning, channels and partnership norms often require local evidence.</p></div>'),'ai-business-playbooks':('AI Business Playbooks | Alan Yeong','Practical AI connected to human judgement.','<header class="page-hero"><div class="wrap narrow"><h1>Make AI useful for the work that matters</h1></div></header><section><div class="wrap split"><div><h2>Human-led, workflow-first</h2><p>Practical playbooks for research, market intelligence, content systems and decision support.</p><a class="button" href="https://buy.stripe.com/cNi9AS7lpf7fa188VqeAg00">Explore available playbooks</a></div><img class="section-photo" src="/images/ai-playbook.jpg" alt="AI playbook"></div></section>'),'contact':('Contact Alan Yeong | Professional Enquiries','Professional and advisory enquiries.',f'<header class="page-hero"><div class="wrap narrow"><h1>Let’s discuss the decision you are facing</h1></div></header><section><div class="wrap narrow">{form}</div></section>'),'privacy-policy':('Privacy Policy | Alan Yeong','Privacy information.','<header class="page-hero"><div class="wrap narrow"><h1>Privacy policy</h1></div></header><div class="page-body wrap narrow prose"><h2>Information collected</h2><p>Enquiry information is used to respond and is not added to a marketing list without separate consent.</p><p><em>This draft requires legal review before production launch.</em></p></div>'),'thank-you':('Thank You | Alan Yeong','Your enquiry has been received.','<section class="page-hero"><div class="wrap narrow"><h1>Thank you.</h1><p class="lead">Your enquiry has been received.</p></div></section>')}
pages['']=(pages[''][0],pages[''][1],pages[''][2]+f'''<section class="cta-band"><div class="wrap split"><div><p class="eyebrow">Professional enquiry</p><h2>Let’s discuss the decision you are facing</h2><p>If you are evaluating an Asian market, interpreting research or exploring a practical use of AI, tell me a little about the situation.</p></div>{form}</div></section>''')

pages['advisory']=('Asia Market, Consumer Intelligence & AI Advisory | Alan Yeong','Decision-led advisory for market entry, consumer intelligence, research interpretation, commercial strategy and practical AI across Asia.','''<header class="page-hero"><div class="wrap narrow"><p class="eyebrow">Advisory</p><h1>Senior perspective for decisions that cannot rely on surface-level answers</h1><p class="lead">I help leaders connect market evidence, consumer behaviour, cultural context and commercial realities—so the next decision is clearer, more grounded and more actionable.</p></div></header><section><div class="wrap split"><div class="page-intro"><p class="eyebrow">Decision-led, not package-led</p><h2>Start with the decision</h2><p>Some assignments begin with a market opportunity. Others begin with conflicting research, a changing consumer, an underperforming proposition or an AI initiative that has not yet become useful work.</p><p>I begin by clarifying the decision, the assumptions surrounding it and the evidence required. The approach is then shaped around the situation rather than forced into a predetermined methodology.</p></div><img class="section-photo" src="/images/advisory-conversation.jpg" alt="A focused advisory discussion around market evidence and business decisions"></div></section><section class="alternate"><div class="wrap"><div class="section-head"><p class="eyebrow">Where I help</p><h2>From evidence to commercial direction</h2></div><div class="service-grid"><article class="service-block"><h3>Asia market entry and growth</h3><p>Assess opportunity, local market structure, consumer expectations, routes to market, critical assumptions and the degree of adaptation required before resources are committed.</p></article><article class="service-block"><h3>Consumer and cultural intelligence</h3><p>Look beneath reported behaviour to understand motivations, trust, cultural meaning, category dynamics and the context surrounding real consumer choices.</p></article><article class="service-block"><h3>Research diagnosis and interpretation</h3><p>Strengthen research questions, evaluate evidence quality, connect fragmented findings and translate technically sound research into implications that leaders can use.</p></article><article class="service-block"><h3>Brand and commercial strategy</h3><p>Connect consumer understanding to positioning, proposition, marketing priorities, customer experience and the commercial decisions required for growth.</p></article><article class="service-block"><h3>AI-enabled intelligence workflows</h3><p>Design practical, human-led workflows for research, synthesis, knowledge management and decision support—with clear review, evidence and accountability boundaries.</p></article><article class="service-block"><h3>Leadership workshops and briefings</h3><p>Help leadership teams examine evidence, challenge assumptions, align around uncertainty and determine the questions that must be answered before action.</p></article></div></div></section><section><div class="wrap"><div class="section-head"><p class="eyebrow">Engagement formats</p><h2>Flexible support around the situation</h2></div><div class="cards"><article class="card"><h3>Executive advisory</h3><p>Focused senior input on an active market, consumer, research or growth decision.</p></article><article class="card"><h3>Assessment</h3><p>A structured review of opportunity, evidence, risks, assumptions and knowledge gaps.</p></article><article class="card"><h3>Project partnership</h3><p>Specialist contribution alongside internal teams, research firms or consulting partners.</p></article><article class="card"><h3>Workshop or briefing</h3><p>Facilitated working sessions that turn information into shared understanding and direction.</p></article></div></div></section><section class="alternate"><div class="wrap"><div class="section-head"><p class="eyebrow">How the work develops</p><h2>A clear path from question to action</h2></div><div class="numbered-process"><article class="process-step"><h3>Frame</h3><p>Define the real decision, stakeholders, constraints and consequences.</p></article><article class="process-step"><h3>Examine</h3><p>Review available evidence, assumptions, cultural context and important gaps.</p></article><article class="process-step"><h3>Interpret</h3><p>Connect signals and findings to strategic and commercial implications.</p></article><article class="process-step"><h3>Act</h3><p>Translate the judgement into priorities, options, next steps and learning needs.</p></article></div></div></section><section><div class="wrap"><div class="evidence-strip"><div class="evidence-item"><strong>25 years</strong>Research, marketing, commercial leadership and consulting</div><div class="evidence-item"><strong>Since 2010</strong>Research exposure across Asian and international markets</div><div class="evidence-item"><strong>Regional depth</strong>Greater China, North Asia, East Asia and Southeast Asia</div><div class="evidence-item"><strong>Builder perspective</strong>Advice informed by founding and operating ventures</div></div></div></section><section class="cta-band"><div class="wrap split"><div><p class="eyebrow">Professional enquiry</p><h2>Bring me the decision—not a polished brief</h2><p>If the situation is still unclear, that is often the right time to begin a conversation.</p></div><div><a class="button secondary" href="/contact/" style="color:#fff;border-color:#fff">Discuss your situation</a></div></div></section>''')

pages['asia-expertise']=('Asia Market Entry and Regional Expertise | Alan Yeong','Asia market experience spanning Greater China, North Asia, Southeast Asia and selected global markets, grounded in consumer and cultural context.','''<header class="page-hero"><div class="wrap narrow"><p class="eyebrow">Asia expertise</p><h1>Asia is not one market—and experience cannot be reduced to a country count</h1><p class="lead">Regional ambition becomes useful only when it is translated through local consumer behaviour, culture, market structure, channels and commercial reality.</p></div></header><section><div class="wrap split"><div class="page-intro"><p class="eyebrow">Regional centre of gravity</p><h2>Asian perspective, developed close to the markets</h2><p>I have conducted and supported research across Asian and international markets since 2010. My broader exposure includes Australia and New Zealand, India, the United Kingdom, Germany and the United States.</p><p>The deepest concentration of my work has developed across Greater China, North and East Asia, and Southeast Asia. An Asian background and experience based in Shanghai helped shape a perspective that treats local context as part of the strategy—not as a localisation step added afterwards.</p></div><img class="section-photo" src="/images/asia-expertise.jpg" alt="Layered market evidence representing the diversity of Asian markets"></div></section><section class="alternate"><div class="wrap"><div class="section-head"><p class="eyebrow">Market experience since 2010</p><h2>Regional depth with wider international exposure</h2><p>This is an experience map, not a claim that every market has the same depth, recency or type of assignment.</p></div><div class="market-groups"><article class="market-group primary"><h3>Primary Asian focus</h3><ul><li>Greater China, including Hong Kong and Taiwan</li><li>Japan and South Korea</li><li>Singapore and Malaysia</li><li>Indonesia and Thailand</li><li>Vietnam and the Philippines</li></ul></article><article class="market-group"><h3>Extended Asia-Pacific</h3><ul><li>Australia</li><li>New Zealand</li><li>India</li></ul></article><article class="market-group"><h3>International exposure</h3><ul><li>United Kingdom</li><li>Germany</li><li>United States</li></ul></article></div></div></section><section><div class="wrap"><div class="section-head"><p class="eyebrow">The questions that matter</p><h2>What travels—and what must be understood locally?</h2><p>A capability may travel across borders. Consumer meaning, trust, pricing expectations, channels, partnerships and the way a category is used often do not.</p></div><div class="lens-grid"><article class="lens"><h3>Culture and meaning</h3><p>How history, language, identity, social norms and relationships shape behaviour.</p></article><article class="lens"><h3>Trust and choice</h3><p>What creates confidence, reduces perceived risk and influences adoption locally.</p></article><article class="lens"><h3>Channels and commerce</h3><p>How discovery, platforms, retail structures, payments and fulfilment alter the route to purchase.</p></article><article class="lens"><h3>Market and category systems</h3><p>How regulation, competition, partnerships, infrastructure and category maturity affect feasibility.</p></article></div></div></section><section class="alternate"><div class="wrap split"><img class="section-photo" src="/images/market-entry.jpg" alt="Market pathways and evidence arranged for an Asia market-entry decision"><div><p class="eyebrow">How I support regional decisions</p><h2>Compare carefully. Adapt deliberately. Learn locally.</h2><p>I help teams identify which parts of a proposition or strategy are genuinely transferable, which require adaptation and which assumptions need fresh local evidence.</p><ul><li>Market-entry and opportunity assessment</li><li>Cross-market consumer and cultural comparison</li><li>Research design and interpretation</li><li>Local context for international teams</li><li>Regional synthesis without flattening country differences</li></ul><a class="button" href="/contact/">Discuss an Asia market question</a></div></div></section><section><div class="wrap narrow"><p class="eyebrow">Related intelligence</p><h2>Follow the markets through the Insights Library</h2><p>Current and future articles will connect regional developments to the decisions they may create for leaders, brands and research teams.</p><a class="button secondary" href="/insights/">Explore Asia insights</a></div></section>''')

articles=[('asia-is-not-one-market','Asia Is Not One Market','Regional opportunity must be balanced with country context.'),('beyond-the-research-report','Beyond the Research Report','Research creates value when findings clarify choices.'),('where-ai-strengthens-judgement','Where AI Strengthens Business Judgement','AI can improve exploration without replacing accountability.')]
