linkedin_cards='''<article class="insight-card"><p class="source-label">LinkedIn article · Research practice</p><h2>Respondent-Quality Diagnosis: Why AI Fraud Detection Is the Most Urgent Problem in Multilingual Southeast Asian Research Panels</h2><p>Why respondent quality, language and AI-enabled fraud now require stronger research controls across Southeast Asia.</p><a class="external" href="https://www.linkedin.com/pulse/respondent-quality-diagnosis-why-ai-fraud-detection-most-yeong-qfq5c" target="_blank" rel="noopener">Read on LinkedIn ↗</a></article><article class="insight-card"><p class="source-label">LinkedIn article · AI and markets</p><h2>Singapore's $1.31 Billion AI Funding Lead—and What It Means for the Rest of the Region</h2><p>A regional signal about investment concentration, ecosystem development and the implications for neighbouring markets.</p><a class="external" href="https://www.linkedin.com/pulse/singapores-131-billion-ai-funding-lead-what-means-rest-yeong-cdwrc" target="_blank" rel="noopener">Read on LinkedIn ↗</a></article><article class="insight-card"><p class="source-label">LinkedIn article · ASEAN commerce</p><h2>Cross-Border QR Interoperability Across 8 of 10 ASEAN Markets</h2><p>What payment interoperability may mean for SMEs, regional commerce and customer experience across ASEAN.</p><a class="external" href="https://www.linkedin.com/pulse/cross-border-qr-interoperability-across-8-10-asean-markets-yeong-nk07c" target="_blank" rel="noopener">Read on LinkedIn ↗</a></article>'''
insights_body=f'''<header class="page-hero"><div class="wrap narrow"><p class="eyebrow">Insights</p><h1>Market signals interpreted for better decisions</h1><p class="lead">Perspectives on Asian markets, consumer behaviour, research quality, digital commerce and practical AI—written to move beyond the headline and examine what a development may mean.</p></div></header><section><div class="wrap"><div class="section-head"><p class="eyebrow">Explore by theme</p><h2>An expanding research and decision library</h2></div><div class="topic-nav"><span>Asia market signals</span><span>Consumer intelligence</span><span>Digital commerce</span><span>AI and decision systems</span><span>Research practice</span><span>Founder notes</span></div><div class="insight-grid">{cards}</div></div></section><section class="alternate"><div class="wrap"><div class="section-head"><p class="eyebrow">Recent writing on LinkedIn</p><h2>Current perspectives awaiting archive migration</h2><p>These articles currently remain on LinkedIn. Once the archive is available, selected pieces can be edited into permanent, searchable pages on this website while preserving their original dates and source links.</p></div><div class="insight-grid">{linkedin_cards}</div></div></section><section><div class="wrap split"><img class="section-photo" src="/images/thought-leadership.jpg" alt="Writing and reviewing ideas about markets, consumers and AI"><div><p class="eyebrow">Editorial approach</p><h2>From signal to implication</h2><p>Each insight should separate the observable development from interpretation and from the decisions it may create. Sources, dates and important limitations will be retained wherever factual claims are used.</p><div class="archive-note"><strong>Archive workflow:</strong> LinkedIn articles will be reviewed, categorised, lightly edited for the web, assigned SEO metadata and connected through related-reading links. Nothing will be bulk-published without checking relevance and evidence.</div></div></div></section><section class="cta-band"><div class="wrap split"><div><p class="eyebrow">Continue the conversation</p><h2>Follow current thinking between longer articles</h2><p>LinkedIn will remain the channel for shorter observations and discussion; this website will become the permanent knowledge library.</p></div><div><a class="button secondary" href="https://www.linkedin.com/in/alankyeong" target="_blank" rel="noopener" style="color:#fff;border-color:#fff">Follow Alan on LinkedIn ↗</a></div></div></section>'''
x=O/'insights';x.mkdir();(x/'index.html').write_text(page('Insights on Asian Markets, Consumers and AI | Alan Yeong','Analysis of Asian markets, consumer intelligence, research quality, digital commerce and practical AI for business decisions.',insights_body,'/insights/'),encoding='utf-8')
for s,t,d in articles:
  x=O/'insights'/s;x.mkdir();body=f'<article class="article wrap narrow"><p class="eyebrow">Insight</p><h1>{t}</h1><p class="lead">{d}</p><div class="prose"><h2>From information to action</h2><p>The goal is to understand which uncertainty deserves attention before an organisation commits.</p></div></article>';(x/'index.html').write_text(page(t+' | Alan Yeong',d,body,f'/insights/{s}/'),encoding='utf-8')
(O/'robots.txt').write_text('User-agent: *\nDisallow: /\n');(O/'404.html').write_text(page('Page Not Found | Alan Yeong','Page not found','<section class="page-hero"><div class="wrap narrow"><h1>Page not found</h1></div></section>','/404.html'),encoding='utf-8')
for html_file in O.rglob('*.html'):
  html_file.write_text(html_file.read_text(encoding='utf-8').replace('/assets.css?v=1.4','/assets.css?v=1.5'),encoding='utf-8')
print(O)
